/**
 * Embedded PDF font (DejaVu Sans, subset).
 *
 * Why embed at all: the PDF's standard 14 fonts are limited to WinAnsi and cannot
 * represent Cyrillic, so a project named "Ошхона шкаф" (which earlier stages
 * support end to end) would render as garbage. Embedding a TrueType subset gives
 * correct glyphs for Latin, Cyrillic and the punctuation the document uses.
 *
 * The subset keeps 465 glyphs: Basic Latin, Latin-1 Supplement, Latin Extended-A,
 * Cyrillic (U+0400-U+045F), General Punctuation, the Uzbek modifier letters
 * (U+02BB/U+02BC) and a few symbols. Regenerate by running pyftsubset against
 * DejaVuSans.ttf / DejaVuSans-Bold.ttf with those ranges.
 *
 * Licence: DejaVu fonts are (c) Bitstream (Bitstream Vera licence) with DejaVu
 * changes; the licence permits redistribution and embedding. See
 * https://dejavu-fonts.github.io/License.html. Only a derived subset is shipped
 * here, not the full font.
 *
 * Stored as base64 so the build needs no binary asset loader and the font travels
 * with the bundle.
 */

/** Base64 of the subsetted DejaVu Sans (regular). */
export const PDF_FONT_REGULAR_B64 =
  '';


/** Base64 of the subsetted DejaVu Sans (bold). */
export const PDF_FONT_BOLD_B64 =
  '';
